<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Application;

use DateInterval;
use Ramsey\Uuid\Uuid;
use Psr\EventDispatcher\EventDispatcherInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\Oidc\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;

class AuthenticateUser
{
    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly LoginGateway $loginRepository,
        private readonly SessionStoreGateway $sessionStore
    ) {
    }

    public function sessionAuthenticated(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $sessionId,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->fillPreLoadById($tenant, $request, $challenges),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce,
            false,
            $sessionId
        );
    }

    public function preAuthenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->fillPreAuthenticated($tenant, $request, $challenges),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce,
            false,
            null
        );
    }

    public function authenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $username,
        string $password,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->validatedUserData($tenant, $username, $password, $request),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce,
            true,
            null
        );
    }

    private function saveIt(
        AuthenticationResult $validation,
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $issuer,
        string $csid,
        string $state,
        string $nonce,
        bool $emitLoginEvent,
        ?string $activeSessionId
    ): PublicLoginAuthResponse {
        if (!$validation->valid) {
            throw new LoginException($validation, $validation->error ?? '', 401, null, $challenges);
        }

        if ($challenges->session && $activeSessionId !== null && $activeSessionId !== '') {
            return $this->buildResponse($validation, $request, $issuer, $state, $nonce, $activeSessionId);
        }

        if (!$challenges->session) {
            $existingSessionId = $this->sessionStore->findActiveSessionIdByCsid($csid);
            if ($existingSessionId !== null && $existingSessionId !== '') {
                return $this->buildResponse($validation, $request, $issuer, $state, $nonce, $existingSessionId);
            }
        }

        if ($emitLoginEvent) {
            $this->dispatcher->dispatch($validation);
        }

        $sessionId = Uuid::uuid4()->toString();
        $sessionExpiration = new DateInterval("P15D");

        $this->sessionStore->saveSession($sessionId, $request->client, $issuer, $challenges, $validation, $csid, $sessionExpiration);

        return $this->buildResponse($validation, $request, $issuer, $state, $nonce, $sessionId);
    }

    private function buildResponse(
        AuthenticationResult $validation,
        AuthenticationRequest $request,
        string $issuer,
        string $state,
        string $nonce,
        string $sessionId
    ): PublicLoginAuthResponse {
        $idData = [
            'typ' => 'ID',
            'nonce' => $nonce,
            'session_state' => $sessionId,
            's_hash' => self::generateHash($state),
        ];
        $sessionExpiration = new DateInterval("P15D");

        return new PublicLoginAuthResponse(
            tenant: $validation->tenant ?? '',
            auth: $validation,
            issuer: $issuer,
            clientId: $request->client->id,
            authExpiration: new DateInterval("PT10M"),
            idData: $idData,
            idExpiration: new DateInterval("PT10M"),
            sessionId: $sessionId,
            sessionExpiration: $sessionExpiration
        );
    }

    public static function generateHash(string $value): string
    {
        $hashedValue = hash('sha256', $value, true);
        $halfHashedValue = substr($hashedValue, 0, intdiv(strlen($hashedValue), 2));
        return rtrim(strtr(base64_encode($halfHashedValue), '+/', '-_'), '=');
    }
}
